        return ""
    if len(items) == 1:
        return items[0]
    if len(items) == 2:
        return f"{items[0]} and {items[1]}"
    return ", ".join(items[:-1]) + f", and {items[-1]}"

def ordinal_suffix(n):
    a = abs(n)
    if 11 <= a % 100 <= 13:
        suf = 'th'
    else:
        suf = {1: 'st', 2: 'nd', 3: 'rd'}.get(a % 10, 'th')
    return f"{n}{suf}"

