def count_distinct_rotations(lst):
    n = len(lst)
    if n == 0:
        return 1
    seen = set()
    for k in range(n):
        seen.add(tuple(lst[k:] + lst[:k]))
    return len(seen)

def wrap_with_indent(text, width, indent):
    words = text.split()
    lines = []
    cur = ""
    for word in words:
        limit = width if not lines else width - indent
        if not cur:
            cur = word
        elif len(cur) + 1 + len(word) <= limit:
            cur += " " + word
        else:
            lines.append(cur)
            cur = word
    if cur:
        lines.append(cur)
    out = []
    for i, line in enumerate(lines):
        out.append(line if i == 0 else " " * indent + line)
    return out

def shift_left_and_fill(lst, n, fill):
    length = len(lst)
    if n <= 0:
        return lst[:]
    if n >= length:
        return [fill] * length
    return lst[n:] + [fill] * n

